# frozen_string_literal: true

require "cases/helper"

module ActiveRecord
  class Relation
    class SelfJoinMergeTest < ActiveRecord::TestCase
      self.use_transactional_tests = false

      # One table joined to itself twice. The parent and children associations
      # each reach the same table through a different alias generated by the
      # association, and predicates on every alias reference the same `status`
      # column.
      class SelfJoinNode < ActiveRecord::Base
        belongs_to :parent,
          class_name: "ActiveRecord::Relation::SelfJoinMergeTest::SelfJoinNode",
          foreign_key: :parent_id
        has_many :children,
          class_name: "ActiveRecord::Relation::SelfJoinMergeTest::SelfJoinNode",
          foreign_key: :parent_id

        scope :active,   -> { where(status: "active") }
        scope :archived, -> { where(status: "archived") }
      end

      PARENTS_ALIAS_NAME  = "parents_self_join_nodes"
      CHILDREN_ALIAS_NAME = "children_self_join_nodes"

      def setup
        @connection = ActiveRecord::Base.lease_connection
        @connection.create_table(:self_join_nodes, force: true) do |t|
          t.string  :label
          t.string  :status
          t.integer :parent_id
        end
        SelfJoinNode.reset_column_information

        # Two self-referential groups. In group A the parent is active; in
        # group B the parent is archived. Every middle node also has a child so
        # both groups satisfy the inner join on the children association.
        @a_parent = SelfJoinNode.create!(label: "A_parent", status: "active")
        @a_child  = SelfJoinNode.create!(label: "A_child",  status: "active", parent_id: @a_parent.id)
        SelfJoinNode.create!(label: "A_grand", status: "active", parent_id: @a_child.id)

        @b_parent = SelfJoinNode.create!(label: "B_parent", status: "archived")
        @b_child  = SelfJoinNode.create!(label: "B_child",  status: "active", parent_id: @b_parent.id)
        SelfJoinNode.create!(label: "B_grand", status: "active", parent_id: @b_child.id)
      end

      def teardown
        @connection.drop_table(:self_join_nodes, if_exists: true)
      end

      # With both aliases filtered as `status = 'active'`, only group A is
      # returned. Merging a scope that replaces the predicate on the parent
      # alias with `status = 'archived'` flips the result to group B, while the
      # children alias predicate stays `active`. A name-based replacement would
      # rewrite the children alias predicate as well, changing the result again.
      def test_merge_replaces_only_the_predicate_on_the_matching_alias
        base = SelfJoinNode.joins(:parent, :children)
          .where(parents_alias[:status].eq("active"))
          .where(children_alias[:status].eq("active"))

        assert_equal [@a_child.id], base.pluck(:id)

        parent_scope = relation_on(parents_alias)
          .where(parents_alias[:status].eq("archived"))
          # A compound expression is mixed in, so identity matching has to walk
          # past the plain equality instead of treating every `status` node alike.
          .where(parents_alias[:status].eq("archived").or(parents_alias[:label].eq("A_child")))

        merged = base.merge(parent_scope)
        sql = merged.to_sql

        # Only the parent alias changes; the association-generated children alias
        # keeps its own predicate even though the column name is identical.
        assert_match %r{"parents_self_join_nodes"\."status" = 'archived'}, sql
        assert_match %r{"children_self_join_nodes"\."status" = 'active'}, sql

        assert_equal [@b_child.id], merged.pluck(:id)
        assert_not_includes merged.pluck(:id), @a_child.id
      end

      def test_merge_targeting_the_children_alias_leaves_the_parent_alias_intact
        base = SelfJoinNode.joins(:parent, :children)
          .where(parents_alias[:status].eq("active"))
          .where(children_alias[:status].eq("active"))

        children_scope = relation_on(children_alias).where(children_alias[:status].eq("archived"))
        merged = base.merge(children_scope)

        assert_match %r{"children_self_join_nodes"\."status" = 'archived'}, merged.to_sql
        assert_match %r{"parents_self_join_nodes"\."status" = 'active'}, merged.to_sql
        # No group has an archived child in the data, so the merged query returns
        # nothing while the untouched base still returns group A.
        assert_empty merged.pluck(:id)
        assert_equal [@a_child.id], base.pluck(:id)
      end

      def test_repeated_where_on_the_same_column_still_uses_the_last_value
        active   = SelfJoinNode.active
        relation = active.merge(SelfJoinNode.archived)

        assert_equal [@b_parent.id], relation.order(:id).pluck(:id)
        assert_equal 1, relation.where_clause.instance_variable_get(:@predicates).size
      end

      private
        def parents_alias
          @parents_alias ||= SelfJoinNode.arel_table.alias(PARENTS_ALIAS_NAME)
        end

        def children_alias
          @children_alias ||= SelfJoinNode.arel_table.alias(CHILDREN_ALIAS_NAME)
        end

        def relation_on(aliased_table)
          predicate_builder = SelfJoinNode.predicate_builder.with(
            ActiveRecord::TableMetadata.new(SelfJoinNode, aliased_table)
          )
          ActiveRecord::Relation.create(
            SelfJoinNode,
            table: aliased_table,
            predicate_builder: predicate_builder
          )
        end
    end
  end
end
